root=B/'stage/56';(root/'test').mkdir(exist_ok=True);(root/'test/http.js').write_text((B/'stage/51/test/http.js').read_text());(root/'test/notes.test.js').write_text('''import {test,before,after} from "node:test";
import assert from "node:assert/strict";
import {application} from "./http.js";
let h,a,b;
async function api(path,method="GET",body,token){const r=await fetch(h.origin+"/api"+path,{method,headers:{"Content-Type":"application/json",...(token?{Authorization:"Bearer "+token}:{})},body:body===undefined?undefined:JSON.stringify(body)});return {status:r.status,data:r.status===204?null:await r.json()};}
before(async()=>{h=await application();a=(await api("/auth/register","POST",{email:" A@example.com ",password:"learn123"})).data.token;b=(await api("/auth/register","POST",{email:"b@example.com",password:"learn123"})).data.token;});after(async()=>h.close());
test("malformed auth input is rejected without crashing the server",async()=>{for(const password of [{},[],3,"x".repeat(129)])assert.equal((await api("/auth/register","POST",{email:"bad@example.com",password})).status,400);assert.equal((await api("/auth/login","POST",{email:{},password:[]})).status,401);assert.equal((await api("/auth/login","POST",{email:"A@example.com",password:"learn123"})).status,200);});
test("owner can create, read, edit and delete; another user cannot see or change the note",async()=>{const r=await api("/notes","POST",{title:"Learning note",body:"Original"},a);assert.equal(r.status,201);const path="/notes/"+r.data.id;for(const method of ["GET","PUT","DELETE"])assert.equal((await api(path,method,method==="PUT"?{title:"Stolen"}:undefined,b)).status,404);assert.deepEqual((await api("/notes","GET",undefined,b)).data,[]);assert.equal((await api(path,"PUT",{title:"Edited",body:"Saved"},a)).status,200);assert.equal((await api(path,"GET",undefined,a)).data.body,"Saved");assert.equal((await api(path,"DELETE",undefined,a)).status,204);assert.equal((await api(path,"GET",undefined,a)).status,404);});
test("invalid note edits preserve the stored note, logout revokes access",async()=>{const r=await api("/notes","POST",{title:"Keep me",body:"Original"},a);const path="/notes/"+r.data.id;for(const body of [{title:3},{title:"Okay",body:{}},{title:"x".repeat(201)}])assert.equal((await api(path,"PUT",body,a)).status,400);assert.equal((await api(path,"GET",undefined,a)).data.body,"Original");assert.equal((await api("/auth/logout","POST",{},a)).status,204);assert.equal((await api("/notes","GET",undefined,a)).status,401);});
''')
(B/'stage/55/test/ledger.test.ts').write_text('''import {test,before,after} from "node:test";
import assert from "node:assert/strict";
import {database,request} from "./database.js";
let h:Awaited<ReturnType<typeof database>>,product:string,main:string,other:string;
before(async()=>{h=await database();product=(await h.admin.query("SELECT id FROM products WHERE sku='SKU-001'")).rows[0].id;main=(await h.admin.query("SELECT id FROM warehouses WHERE name='Main'")).rows[0].id;other=(await h.admin.query("SELECT id FROM warehouses WHERE name='Overflow'")).rows[0].id;});after(async()=>{if(h)await h.close();});
const api=(path:string,body:unknown)=>request(h.origin,"/api/"+path,"POST",body);
test("fractional, nonnumeric, unbounded and malformed quantities leave stock unchanged",async()=>{const count=await h.admin.query("SELECT count(*) FROM movements");for(const delta of [1.2,"3",0,2147483648,null])assert.equal((await api("movements",{productId:product,warehouseId:main,delta})).status,400);assert.equal((await api("movements",{productId:product,warehouseId:main,delta:1,reason:{}})).status,400);assert.deepEqual((await h.admin.query("SELECT count(*) FROM movements")).rows,count.rows);});
test("two simultaneous issues cannot both spend the same stock",async()=>{const results=await Promise.all([1,2].map(()=>api("movements",{productId:product,warehouseId:main,delta:-30})));assert.deepEqual(results.map(r=>r.status).sort(),[201,400]);assert.equal(Number((await h.admin.query("SELECT sum(delta) AS n FROM movements WHERE product_id=$1 AND warehouse_id=$2",[product,main])).rows[0].n),10);});
test("transfer conserves stock; a late failure rolls the debit back",async()=>{await h.admin.query(`CREATE FUNCTION reject_credit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.reason = 'force failure' AND NEW.delta > 0 THEN RAISE EXCEPTION 'test failure'; END IF; RETURN NEW; END $$; CREATE TRIGGER reject_credit BEFORE INSERT ON movements FOR EACH ROW EXECUTE FUNCTION reject_credit();`);const count=(await h.admin.query("SELECT count(*) FROM movements")).rows;assert.equal((await api("transfers",{productId:product,fromWarehouseId:main,toWarehouseId:other,quantity:3,reason:"force failure"})).status,500);assert.deepEqual((await h.admin.query("SELECT count(*) FROM movements")).rows,count);assert.equal((await api("transfers",{productId:product,fromWarehouseId:main,toWarehouseId:other,quantity:3})).status,201);assert.equal(Number((await h.admin.query("SELECT sum(delta) AS n FROM movements WHERE product_id=$1",[product])).rows[0].n),10);});
''')
